"use client";

import { ArrowLeft, PenTool, RotateCcw } from "lucide-react";
import { useId, useState } from "react";
import { Button } from "@/components/ui/button";
import { parsePath } from "./parse";
import { type EditorStyle, VectorEditor } from "./vector-editor";

const NOT_FOUND_PATH = `
	M 20 165 L 20 130 L 105 25 L 150 25 L 150 125 L 172 125 L 172 165 L 150 165 L 150 210 L 105 210 L 105 165 Z
	M 105 125 L 105 82 L 70 125 Z
	M 280 25 C 225 25 195 62 195 118 C 195 174 225 210 280 210 C 335 210 365 174 365 118 C 365 62 335 25 280 25 Z
	M 280 72 C 302 72 314 88 314 118 C 314 148 302 163 280 163 C 258 163 246 148 246 118 C 246 88 258 72 280 72 Z
	M 388 165 L 388 130 L 473 25 L 518 25 L 518 125 L 540 125 L 540 165 L 518 165 L 518 210 L 473 210 L 473 165 Z
	M 473 125 L 473 82 L 438 125 Z
`;

const INITIAL_PATH = parsePath(NOT_FOUND_PATH);

/** Figma's selection blue, kept as the editor's signature accent. */
const ACCENT = "#0d99ff";

const EDITOR_STYLE: EditorStyle = {
	accent: ACCENT,
	arm: `color-mix(in oklab, ${ACCENT} 45%, var(--background))`,
	anchorR: 4,
	handleR: 3.25,
	hitR: 12,
	pointFill: "var(--background)",
	fill: ACCENT,
	fillOpacity: 0.04,
	stroke: ACCENT,
	strokeWidth: 1.25,
	showRig: true,
	fillRule: "evenodd",
};

export default function NotFound01() {
	const [path, setPath] = useState(INITIAL_PATH);
	const hintId = useId();
	const edited = path !== INITIAL_PATH;

	return (
		<section className="relative isolate flex min-h-svh flex-col overflow-hidden bg-background text-foreground">
			<div
				aria-hidden="true"
				className="pointer-events-none absolute inset-0 -z-10 bg-[linear-gradient(to_right,var(--border)_1px,transparent_1px),linear-gradient(to_bottom,var(--border)_1px,transparent_1px)] bg-size-[24px_24px] opacity-50 [mask-image:radial-gradient(ellipse_70%_60%_at_50%_40%,black,transparent)]"
			/>

			<div className="flex flex-1 flex-col items-center justify-center px-4 py-16 sm:px-8 sm:py-24">
				<figure className="w-full max-w-[40rem] px-2 sm:px-10">
					<div className="mb-4 flex h-6 items-center justify-between gap-3">
						<span className="inline-flex items-center gap-1.5 font-mono text-muted-foreground text-xs">
							<PenTool aria-hidden="true" className="size-3.5" />
							404.svg
						</span>
						<Button
							variant="ghost"
							size="xs"
							className="text-muted-foreground"
							disabled={!edited}
							onClick={() => setPath(INITIAL_PATH)}
						>
							<RotateCcw data-icon="inline-start" />
							Reset
						</Button>
					</div>

					<VectorEditor
						path={path}
						onChange={setPath}
						style={EDITOR_STYLE}
						viewBox={[0, 0, 560, 235]}
						width={560}
						height={235}
						className="h-auto w-full"
						ariaLabel="Editable 404 vector"
						ariaDescribedBy={hintId}
					/>

					<figcaption
						id={hintId}
						className="mt-5 text-balance text-center text-muted-foreground text-xs"
					>
						Drag any point to reshape the 404.
						<span className="hidden sm:inline">
							{" "}
							Arrow keys nudge, Shift moves by 10, [ and ] switch points, Alt
							breaks a curve handle.
						</span>
					</figcaption>
				</figure>

				<div className="mt-12 flex max-w-xl flex-col items-center text-center sm:mt-14">
					<h1 className="text-balance font-medium text-3xl tracking-tight sm:text-5xl sm:tracking-[-0.04em]">
						This page slipped off the canvas.
					</h1>
					<p className="mt-4 max-w-md text-pretty text-base text-muted-foreground leading-relaxed">
						The layer you were looking for was moved, renamed, or never made it
						past the first draft.
					</p>
					<Button
						className="mt-8 active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100"
						size="lg"
						nativeButton={false}
						render={<a href="/" />}
					>
						<ArrowLeft data-icon="inline-start" />
						Back to home
					</Button>
				</div>
			</div>
		</section>
	);
}

"use client";

import {
	type KeyboardEvent as ReactKeyboardEvent,
	type PointerEvent as ReactPointerEvent,
	useEffect,
	useRef,
	useState,
} from "react";
import { cn } from "@/lib/utils";
import { serializePath } from "./parse";
import type { Anchor, Vec, VectorPath } from "./types";
import { add, sub, v } from "./types";

export type Mirror = "none" | "angle" | "angle-length";

/**
 * Colors accept any CSS color, including `var(--token)` and `color-mix()`.
 * Sizes are in screen pixels and stay constant however the canvas scales.
 */
export interface EditorStyle {
	accent: string;
	arm: string;
	anchorR: number;
	handleR: number;
	hitR: number;
	pointFill: string;
	fill: string;
	fillOpacity: number;
	stroke: string;
	strokeWidth: number;
	showRig: boolean;
	fillRule: "nonzero" | "evenodd";
}

export const DEFAULT_EDITOR: EditorStyle = {
	accent: "#0d99ff",
	arm: "color-mix(in oklab, #0d99ff 45%, var(--background))",
	anchorR: 4,
	handleR: 3.2,
	hitR: 12,
	pointFill: "var(--background)",
	fill: "#0d99ff",
	fillOpacity: 0.08,
	stroke: "#0d99ff",
	strokeWidth: 1.5,
	showRig: true,
	fillRule: "evenodd",
};

type Side = "in" | "out";

type Drag =
	| { kind: "anchor"; index: number; offset: Vec }
	| {
			kind: "handle";
			index: number;
			side: Side;
			mirror: Mirror;
			offset: Vec;
	  };

type PointKey = `a${number}` | `in${number}` | `out${number}`;

function arrowDelta(key: string, amount: number): Vec | null {
	switch (key) {
		case "ArrowLeft":
			return v(-amount, 0);
		case "ArrowRight":
			return v(amount, 0);
		case "ArrowUp":
			return v(0, -amount);
		case "ArrowDown":
			return v(0, amount);
		default:
			return null;
	}
}

/** Every editable point in reading order: anchor, then its handles. */
function pointKeys(path: VectorPath, showRig: boolean): PointKey[] {
	if (!showRig) return [];
	const keys: PointKey[] = [];
	path.anchors.forEach((anchor, index) => {
		if (anchor.in) keys.push(`in${index}`);
		keys.push(`a${index}`);
		if (anchor.out) keys.push(`out${index}`);
	});
	return keys;
}

const round = (value: number) => Math.round(value);

export function VectorEditor({
	path,
	onChange,
	style = DEFAULT_EDITOR,
	mirror = "angle-length",
	viewBox,
	width,
	height,
	className,
	ariaLabel = "Editable vector",
	ariaDescribedBy,
}: {
	path: VectorPath;
	onChange: (next: VectorPath) => void;
	style?: EditorStyle;
	mirror?: Mirror;
	viewBox: [number, number, number, number];
	width?: number;
	height?: number;
	className?: string;
	ariaLabel?: string;
	ariaDescribedBy?: string;
}) {
	const svgRef = useRef<SVGSVGElement>(null);
	const drag = useRef<Drag | null>(null);
	const pathRef = useRef(path);
	pathRef.current = path;
	const pending = useRef<Vec | null>(null);
	const animationFrame = useRef(0);
	const [active, setActive] = useState<PointKey | null>(null);
	const [dragging, setDragging] = useState(false);
	const [scale, setScale] = useState(1);

	// Keep points and hit areas a constant on-screen size as the canvas scales.
	useEffect(() => {
		const svg = svgRef.current;
		if (!svg) return;
		const update = () => {
			const rendered = svg.getBoundingClientRect().width;
			if (rendered > 0) setScale(rendered / viewBox[2]);
		};
		update();
		const observer = new ResizeObserver(update);
		observer.observe(svg);
		return () => observer.disconnect();
	}, [viewBox[2]]);

	useEffect(
		() => () => {
			if (animationFrame.current) cancelAnimationFrame(animationFrame.current);
		},
		[],
	);

	const unit = 1 / (scale || 1);
	const anchorR = style.anchorR * unit;
	const handleR = style.handleR * unit;
	const hitR = style.hitR * unit;

	const keys = pointKeys(path, style.showRig);
	const tabStop = active && keys.includes(active) ? active : keys[0];

	function toUser(event: { clientX: number; clientY: number }): Vec {
		const svg = svgRef.current;
		const matrix = svg?.getScreenCTM();
		if (!svg || !matrix) return v(0, 0);
		const point = svg.createSVGPoint();
		point.x = event.clientX;
		point.y = event.clientY;
		const transformed = point.matrixTransform(matrix.inverse());
		return v(transformed.x, transformed.y);
	}

	function beginDrag(event: ReactPointerEvent, next: Drag, key: PointKey) {
		event.stopPropagation();
		event.preventDefault();
		const target = event.currentTarget as SVGGElement;
		target.setPointerCapture(event.pointerId);
		target.focus({ preventScroll: true });
		drag.current = next;
		setActive(key);
		setDragging(true);
	}

	function startAnchor(event: ReactPointerEvent, index: number) {
		if (drag.current || event.button !== 0) return;
		const position = pathRef.current.anchors[index].p;
		beginDrag(
			event,
			{ kind: "anchor", index, offset: sub(position, toUser(event)) },
			`a${index}`,
		);
	}

	function startHandle(event: ReactPointerEvent, index: number, side: Side) {
		if (drag.current || event.button !== 0) return;
		const position = pathRef.current.anchors[index][side];
		if (!position) return;
		beginDrag(
			event,
			{
				kind: "handle",
				index,
				side,
				mirror: event.altKey ? "none" : mirror,
				offset: sub(position, toUser(event)),
			},
			`${side}${index}`,
		);
	}

	function applyDrag(activeDrag: Drag, pointer: Vec): VectorPath {
		const anchors = pathRef.current.anchors.map((anchor) => ({
			p: { ...anchor.p },
			in: anchor.in ? { ...anchor.in } : null,
			out: anchor.out ? { ...anchor.out } : null,
		})) as Anchor[];
		const target = add(pointer, activeDrag.offset);
		const anchor = anchors[activeDrag.index];

		if (activeDrag.kind === "anchor") {
			const delta = sub(target, anchor.p);
			anchor.p = target;
			if (anchor.in) anchor.in = add(anchor.in, delta);
			if (anchor.out) anchor.out = add(anchor.out, delta);
		} else {
			anchor[activeDrag.side] = target;
			const other = activeDrag.side === "out" ? anchor.in : anchor.out;
			if (activeDrag.mirror !== "none" && other) {
				const relative = sub(target, anchor.p);
				const relativeLength = Math.hypot(relative.x, relative.y) || 1;
				const length =
					activeDrag.mirror === "angle-length"
						? relativeLength
						: Math.hypot(other.x - anchor.p.x, other.y - anchor.p.y);
				const opposite = {
					x: anchor.p.x - (relative.x / relativeLength) * length,
					y: anchor.p.y - (relative.y / relativeLength) * length,
				};
				if (activeDrag.side === "out") anchor.in = opposite;
				else anchor.out = opposite;
			}
		}

		return {
			anchors,
			starts: pathRef.current.starts,
			closed: pathRef.current.closed,
		};
	}

	function commit(next: VectorPath) {
		pathRef.current = next;
		onChange(next);
	}

	function onMove(event: ReactPointerEvent) {
		if (!drag.current) return;
		pending.current = toUser(event);
		if (animationFrame.current) return;
		animationFrame.current = requestAnimationFrame(() => {
			animationFrame.current = 0;
			if (drag.current && pending.current) {
				commit(applyDrag(drag.current, pending.current));
			}
		});
	}

	function endDrag(event: ReactPointerEvent) {
		if (!drag.current) return;
		if (animationFrame.current) {
			cancelAnimationFrame(animationFrame.current);
			animationFrame.current = 0;
			if (pending.current) commit(applyDrag(drag.current, pending.current));
		}
		try {
			(event.target as Element).releasePointerCapture(event.pointerId);
		} catch {
			// Pointer capture may already be released by the browser.
		}
		drag.current = null;
		pending.current = null;
		setDragging(false);
	}

	function focusPoint(key: PointKey) {
		setActive(key);
		svgRef.current
			?.querySelector<SVGGElement>(`[data-point="${key}"]`)
			?.focus({ preventScroll: true });
	}

	function onPointKeyDown(
		event: ReactKeyboardEvent,
		key: PointKey,
		activeDrag: Drag,
		position: Vec,
	) {
		if (event.key === "]" || event.key === "[") {
			event.preventDefault();
			const index = keys.indexOf(key);
			const step = event.key === "]" ? 1 : -1;
			focusPoint(keys[(index + step + keys.length) % keys.length]);
			return;
		}
		if (event.key === "Escape") {
			(event.currentTarget as SVGGElement).blur();
			return;
		}
		const delta = arrowDelta(event.key, event.shiftKey ? 10 : 1);
		if (!delta) return;
		event.preventDefault();
		commit(applyDrag({ ...activeDrag, offset: v(0, 0) }, add(position, delta)));
	}

	const d = serializePath(path);
	const arms: { key: string; ax: number; ay: number; hx: number; hy: number }[] =
		[];
	if (style.showRig) {
		path.anchors.forEach((anchor, index) => {
			for (const side of ["in", "out"] as const) {
				const handle = anchor[side];
				if (!handle) continue;
				arms.push({
					key: `${side}${index}`,
					ax: anchor.p.x,
					ay: anchor.p.y,
					hx: handle.x,
					hy: handle.y,
				});
			}
		});
	}

	const pointProps = (key: PointKey) => ({
		point: key,
		active: active === key,
		tabIndex: key === tabStop ? 0 : -1,
		onFocus: () => setActive(key),
		hitR,
		accent: style.accent,
		fill: style.pointFill,
	});

	return (
		<svg
			ref={svgRef}
			role="group"
			aria-roledescription="vector editor"
			aria-label={ariaLabel}
			aria-describedby={ariaDescribedBy}
			viewBox={viewBox.join(" ")}
			width={width ?? viewBox[2]}
			height={height ?? viewBox[3]}
			className={cn(
				"block select-none overflow-visible",
				dragging && "cursor-grabbing",
				className,
			)}
			onPointerMove={onMove}
			onPointerUp={endDrag}
			onPointerCancel={endDrag}
			onLostPointerCapture={endDrag}
		>
			<path
				d={d}
				fillRule={style.fillRule}
				vectorEffect="non-scaling-stroke"
				style={{
					fill: style.fill,
					fillOpacity: style.fillOpacity,
					stroke: style.stroke,
					strokeWidth: style.strokeWidth,
				}}
			/>

			{style.showRig ? (
				<g>
					<g
						aria-hidden="true"
						style={{
							stroke: style.arm,
							strokeWidth: Math.max(0.75, style.strokeWidth * 0.75),
						}}
					>
						{arms.map((arm) => (
							<line
								key={arm.key}
								x1={arm.ax}
								y1={arm.ay}
								x2={arm.hx}
								y2={arm.hy}
								vectorEffect="non-scaling-stroke"
							/>
						))}
					</g>

					{path.anchors.map((anchor, index) =>
						(["in", "out"] as const).map((side) => {
							const handle = anchor[side];
							if (!handle) return null;
							const key: PointKey = `${side}${index}`;
							return (
								<Point
									key={key}
									{...pointProps(key)}
									shape="diamond"
									cx={handle.x}
									cy={handle.y}
									r={handleR}
									label={`${side === "in" ? "Incoming" : "Outgoing"} handle of anchor ${index + 1}, at ${round(handle.x)}, ${round(handle.y)}`}
									onPointerDown={(event) => startHandle(event, index, side)}
									onKeyDown={(event) =>
										onPointKeyDown(
											event,
											key,
											{
												kind: "handle",
												index,
												side,
												mirror: event.altKey ? "none" : mirror,
												offset: v(0, 0),
											},
											handle,
										)
									}
								/>
							);
						}),
					)}

					{path.anchors.map((anchor, index) => {
						const key: PointKey = `a${index}`;
						return (
							<Point
								key={key}
								{...pointProps(key)}
								shape="circle"
								cx={anchor.p.x}
								cy={anchor.p.y}
								r={anchorR}
								label={`Anchor ${index + 1} of ${path.anchors.length}, at ${round(anchor.p.x)}, ${round(anchor.p.y)}`}
								onPointerDown={(event) => startAnchor(event, index)}
								onKeyDown={(event) =>
									onPointKeyDown(
										event,
										key,
										{ kind: "anchor", index, offset: v(0, 0) },
										anchor.p,
									)
								}
							/>
						);
					})}
				</g>
			) : null}
		</svg>
	);
}

function Point({
	shape,
	point,
	cx,
	cy,
	r,
	hitR,
	accent,
	fill,
	active,
	tabIndex,
	label,
	onFocus,
	onPointerDown,
	onKeyDown,
}: {
	shape: "circle" | "diamond";
	point: PointKey;
	cx: number;
	cy: number;
	r: number;
	hitR: number;
	accent: string;
	fill: string;
	active: boolean;
	tabIndex: number;
	label: string;
	onFocus: () => void;
	onPointerDown: (event: ReactPointerEvent<SVGGElement>) => void;
	onKeyDown: (event: ReactKeyboardEvent<SVGGElement>) => void;
}) {
	const visual = {
		fill: active ? accent : fill,
		stroke: accent,
		strokeWidth: 1.25,
	};

	return (
		// biome-ignore lint/a11y/useSemanticElements: SVG points cannot be <button> elements.
		<g
			role="button"
			aria-roledescription="draggable point"
			aria-label={label}
			data-point={point}
			tabIndex={tabIndex}
			className="group cursor-grab touch-none outline-none"
			onFocus={onFocus}
			onPointerDown={onPointerDown}
			onKeyDown={onKeyDown}
		>
			<circle cx={cx} cy={cy} r={hitR} fill="transparent" />
			<circle
				cx={cx}
				cy={cy}
				r={r * 2}
				fill="none"
				vectorEffect="non-scaling-stroke"
				style={{ stroke: accent, strokeWidth: 1.5 }}
				className="opacity-0 transition-opacity duration-150 group-hover:opacity-40 group-focus-visible:opacity-100 motion-reduce:transition-none"
			/>
			{shape === "circle" ? (
				<circle
					cx={cx}
					cy={cy}
					r={r}
					vectorEffect="non-scaling-stroke"
					style={visual}
				/>
			) : (
				<rect
					x={cx - r}
					y={cy - r}
					width={r * 2}
					height={r * 2}
					vectorEffect="non-scaling-stroke"
					style={{
						...visual,
						transform: "rotate(45deg)",
						transformBox: "fill-box",
						transformOrigin: "50% 50%",
					}}
				/>
			)}
		</g>
	);
}

import type { Anchor, Vec, VectorPath } from "./types";
import { subRange, v } from "./types";

type Token = { cmd: string; args: number[] };

function tokenize(d: string): Token[] {
	const tokens: Token[] = [];
	const pattern = /([MmLlHhVvCcSsQqTtAaZz])|(-?\d*\.?\d+(?:e[-+]?\d+)?)/gi;
	let match = pattern.exec(d);
	let current: Token | null = null;

	while (match) {
		if (match[1]) {
			current = { cmd: match[1], args: [] };
			tokens.push(current);
		} else if (current) {
			current.args.push(Number.parseFloat(match[2]));
		}
		match = pattern.exec(d);
	}

	return tokens;
}

export function parsePath(d: string): VectorPath {
	const tokens = tokenize(d);
	const anchors: Anchor[] = [];
	const starts: number[] = [];
	const closed: boolean[] = [];
	let current = v(0, 0);
	let start = v(0, 0);
	let previousControl: Vec | null = null;
	let previousCommand = "";

	const push = (p: Vec) => anchors.push({ p, out: null, in: null });
	const last = () => anchors[anchors.length - 1];
	const dedupeClose = () => {
		if (!starts.length) return;
		const startIndex = starts.at(-1) ?? 0;
		if (anchors.length - startIndex < 2) return;

		const first = anchors[startIndex].p;
		const final = anchors.at(-1);
		if (
			final &&
			Math.abs(first.x - final.p.x) < 0.01 &&
			Math.abs(first.y - final.p.y) < 0.01
		) {
			anchors[startIndex].in = final.in;
			anchors.pop();
		}
	};

	for (const { cmd, args } of tokens) {
		const relative = cmd === cmd.toLowerCase();
		const command = cmd.toUpperCase();
		let index = 0;
		const number = () => args[index++];
		const point = (): Vec => {
			const x = number();
			const y = number();
			return relative ? { x: current.x + x, y: current.y + y } : { x, y };
		};

		switch (command) {
			case "M": {
				if (starts.length && closed.at(-1)) dedupeClose();
				current = point();
				start = current;
				starts.push(anchors.length);
				closed.push(false);
				push(current);
				while (index < args.length) {
					current = point();
					push(current);
				}
				previousControl = null;
				break;
			}
			case "L": {
				while (index < args.length) {
					current = point();
					push(current);
				}
				previousControl = null;
				break;
			}
			case "H": {
				while (index < args.length) {
					const x = number();
					current = { x: relative ? current.x + x : x, y: current.y };
					push(current);
				}
				previousControl = null;
				break;
			}
			case "V": {
				while (index < args.length) {
					const y = number();
					current = { x: current.x, y: relative ? current.y + y : y };
					push(current);
				}
				previousControl = null;
				break;
			}
			case "C": {
				while (index < args.length) {
					const firstControl = point();
					const secondControl = point();
					const end = point();
					last().out = firstControl;
					push(end);
					last().in = secondControl;
					current = end;
					previousControl = secondControl;
				}
				break;
			}
			case "S": {
				while (index < args.length) {
					const canReflect =
						previousCommand === "C" || previousCommand === "S" || index > 0;
					const firstControl = canReflect
						? {
								x: 2 * current.x - (previousControl?.x ?? current.x),
								y: 2 * current.y - (previousControl?.y ?? current.y),
							}
						: current;
					const secondControl = point();
					const end = point();
					last().out = firstControl;
					push(end);
					last().in = secondControl;
					current = end;
					previousControl = secondControl;
				}
				break;
			}
			case "Q": {
				while (index < args.length) {
					const quadraticControl: Vec = point();
					const end = point();
					last().out = {
						x: current.x + (2 / 3) * (quadraticControl.x - current.x),
						y: current.y + (2 / 3) * (quadraticControl.y - current.y),
					};
					push(end);
					last().in = {
						x: end.x + (2 / 3) * (quadraticControl.x - end.x),
						y: end.y + (2 / 3) * (quadraticControl.y - end.y),
					};
					current = end;
					previousControl = quadraticControl;
				}
				break;
			}
			case "T": {
				while (index < args.length) {
					const canReflect =
						previousCommand === "Q" || previousCommand === "T" || index > 0;
					const quadraticControl: Vec = canReflect
						? {
								x: 2 * current.x - (previousControl?.x ?? current.x),
								y: 2 * current.y - (previousControl?.y ?? current.y),
							}
						: current;
					const end = point();
					last().out = {
						x: current.x + (2 / 3) * (quadraticControl.x - current.x),
						y: current.y + (2 / 3) * (quadraticControl.y - current.y),
					};
					push(end);
					last().in = {
						x: end.x + (2 / 3) * (quadraticControl.x - end.x),
						y: end.y + (2 / 3) * (quadraticControl.y - end.y),
					};
					current = end;
					previousControl = quadraticControl;
				}
				break;
			}
			case "Z": {
				if (closed.length) closed[closed.length - 1] = true;
				current = start;
				previousControl = null;
				break;
			}
			case "A":
				throw new Error(
					"Arc commands (A) are not supported by the point editor.",
				);
			default:
				throw new Error(`Unsupported path command: ${cmd}`);
		}

		previousCommand = command;
	}

	if (starts.length && closed.at(-1)) dedupeClose();
	return { anchors, starts, closed };
}

const formatNumber = (value: number) => String(Math.round(value * 100) / 100);

export function serializePath(path: VectorPath): string {
	const { anchors, starts, closed } = path;
	if (!anchors.length || !starts.length) return "";
	const parts: string[] = [];

	for (let index = 0; index < starts.length; index++) {
		const [begin, end] = subRange(path, index);
		const count = end - begin;
		if (!count) continue;

		parts.push(
			`M ${formatNumber(anchors[begin].p.x)} ${formatNumber(anchors[begin].p.y)}`,
		);
		const segmentCount = closed[index] ? count : count - 1;

		for (let segment = 0; segment < segmentCount; segment++) {
			const anchor = anchors[begin + segment];
			const next = anchors[begin + ((segment + 1) % count)];
			if (anchor.out || next.in) {
				const firstControl = anchor.out ?? anchor.p;
				const secondControl = next.in ?? next.p;
				parts.push(
					`C ${formatNumber(firstControl.x)} ${formatNumber(firstControl.y)} ${formatNumber(secondControl.x)} ${formatNumber(secondControl.y)} ${formatNumber(next.p.x)} ${formatNumber(next.p.y)}`,
				);
			} else {
				parts.push(`L ${formatNumber(next.p.x)} ${formatNumber(next.p.y)}`);
			}
		}

		if (closed[index]) parts.push("Z");
	}

	return parts.join(" ");
}

export interface Vec {
	x: number;
	y: number;
}

export interface Anchor {
	p: Vec;
	out: Vec | null;
	in: Vec | null;
}

export interface VectorPath {
	anchors: Anchor[];
	starts: number[];
	closed: boolean[];
}

export const v = (x: number, y: number): Vec => ({ x, y });
export const add = (a: Vec, b: Vec): Vec => ({
	x: a.x + b.x,
	y: a.y + b.y,
});
export const sub = (a: Vec, b: Vec): Vec => ({
	x: a.x - b.x,
	y: a.y - b.y,
});

export function subRange(path: VectorPath, index: number): [number, number] {
	return [
		path.starts[index],
		index + 1 < path.starts.length
			? path.starts[index + 1]
			: path.anchors.length,
	];
}
